// Built native pages; fixture contracts generated by prepare_business_item_browser.py.
// Browser writes remain synthetic; real source, transaction and HTTP gates have separate tests.
import assert from "node:assert/strict";
import { spawn } from "node:child_process";
import { existsSync } from "node:fs";
import { mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
import { createServer } from "node:net";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";
import { businessItemCopy } from "../apps/web/lib/business-item-copy.ts";
import { AccessibilityAudit } from "./browser-accessibility.mjs";
import { Cdp, evaluate, sleep } from "./browser-cdp.mjs";

const root = resolve(import.meta.dirname, ".."),
  visual = process.argv.includes("--visual-check");
const fixtures = JSON.parse(
  await readFile(
    join(root, ".tmp/business-item-browser-fixtures.json"),
    "utf8",
  ),
);
const chrome = [
  process.env.CHROME_BIN,
  "C:/Program Files/Google/Chrome/Application/chrome.exe",
  "C:/Program Files (x86)/Google/Chrome/Application/chrome.exe",
]
  .filter(Boolean)
  .find(existsSync);
assert.ok(chrome);
const reserve = createServer();
await new Promise((done) => reserve.listen(0, "127.0.0.1", done));
const port = reserve.address().port;
await new Promise((done) => reserve.close(done));
const base = `http://127.0.0.1:${port}`;
const server = spawn(
  process.execPath,
  [
    join(root, "node_modules/next/dist/bin/next"),
    "start",
    "-H",
    "127.0.0.1",
    "-p",
    String(port),
  ],
  { cwd: join(root, "apps/web"), stdio: "ignore", windowsHide: true },
);
const profile = await mkdtemp(join(tmpdir(), "helvetic-item-work-"));
const browser = spawn(
  chrome,
  [
    "--headless=new",
    "--no-first-run",
    "--no-default-browser-check",
    "--remote-debugging-port=0",
    `--user-data-dir=${profile}`,
    "about:blank",
  ],
  { stdio: "ignore", windowsHide: true },
);
const routes = {
  tenders: "tender-watch",
  ip: "trademark-watch",
  auctions: "auction-watch",
};
const audit = new AccessibilityAudit(
  visual ? "business-item-visual" : "business-item-work",
);
let cdp,
  domain = "tenders",
  locale = "en-CH",
  user = "owner",
  role = "organization_admin",
  state,
  nav = 0,
  conflict = false,
  denied = false,
  sourceUnavailable = false,
  delayed = false,
  held = null;
const errors = [],
  requests = [],
  writes = [];
const person = (id) =>
  id ? { id, name: id === "owner" ? "Owner" : "Peer", available: true } : null;
function reset(kind) {
  domain = kind;
  state = structuredClone(fixtures[kind]);
  user = "owner";
  role = "organization_admin";
  conflict = false;
  denied = false;
  sourceUnavailable = false;
  delayed = false;
  held = null;
}
async function wait(check, message) {
  for (let i = 0; i < 250; i++) {
    if (
      await Promise.resolve()
        .then(check)
        .catch(() => false)
    )
      return;
    await sleep(100);
  }
  throw Error(message);
}
async function response(requestId, body, code = 200) {
  await cdp
    .send("Fetch.fulfillRequest", {
      requestId,
      responseCode: code,
      responseHeaders: [
        { name: "Content-Type", value: "application/json" },
        { name: "Cache-Control", value: "no-store" },
      ],
      body: Buffer.from(JSON.stringify(body)).toString("base64"),
    })
    .catch(() => {});
}
async function click(selector) {
  await wait(
    () =>
      evaluate(
        cdp,
        `!!document.querySelector(${JSON.stringify(selector)})&&!document.querySelector(${JSON.stringify(selector)}).disabled`,
      ),
    `Missing ${selector}`,
  );
  await evaluate(
    cdp,
    `document.querySelector(${JSON.stringify(selector)}).click()`,
  );
}
async function button(label) {
  await wait(
    () =>
      evaluate(
        cdp,
        `(()=>{const el=[...document.querySelectorAll('[data-business-item-work] button')].find(el=>el.textContent.trim()===${JSON.stringify(label)}&&!el.disabled);if(!el)return false;el.click();return true;})()`,
      ),
    `Missing enabled button: ${label}`,
  );
}
async function value(selector, text, tag = "select") {
  const klass =
    tag === "textarea" ? "HTMLTextAreaElement" : "HTMLSelectElement";
  await evaluate(
    cdp,
    `(()=>{const el=document.querySelector(${JSON.stringify(selector)});Object.getOwnPropertyDescriptor(${klass}.prototype,'value').set.call(el,${JSON.stringify(text)});el.dispatchEvent(new Event(${JSON.stringify(tag === "textarea" ? "input" : "change")},{bubbles:true}));})()`,
  );
}
async function navigate(detail = true) {
  await evaluate(cdp, "window.__itemPrevious=true");
  const suffix =
    domain === "tenders"
      ? `&dossier=${state.detail.id}`
      : domain === "ip"
        ? `&candidate=${state.detail.id}`
        : "";
  await cdp.send("Page.navigate", {
    url: `${base}/${routes[domain]}?monitor=${state.monitor.id}${detail ? suffix : ""}&locale=${locale}&qa=${++nav}`,
  });
  await wait(
    () =>
      evaluate(
        cdp,
        `!window.__itemPrevious&&document.documentElement.lang===${JSON.stringify(locale)}&&!!document.querySelector(${JSON.stringify(detail ? "[data-business-item-work]" : "[data-business-assignment-filter]")})`,
      ),
    "Native page did not load",
  );
}
async function open() {
  await wait(
    () =>
      evaluate(
        cdp,
        `(()=>{const el=document.querySelector('[data-business-item-work]');if(!el||Number(el.dataset.itemVersion)!==${state.detail.version})return false;if(!el.open)el.querySelector('summary').click();return true;})()`,
      ),
    "Missing item panel",
  );
  await wait(
    () =>
      evaluate(
        cdp,
        `document.querySelector('[data-business-item-work]')?.innerText.includes(${JSON.stringify(sourceUnavailable ? businessItemCopy[locale].unavailable : businessItemCopy[locale].history)})`,
      ),
    "Item history did not load",
  );
}
async function check(name) {
  await evaluate(
    cdp,
    "Promise.all(document.getAnimations().filter(a=>a.effect?.getComputedTiming().iterations!==Infinity).map(a=>a.finished.catch(()=>{})))",
  );
  assert.ok(
    await evaluate(cdp, "document.documentElement.scrollWidth<=innerWidth+1"),
  );
  await audit.check(cdp, name, "[data-business-item-work]");
}
function workPage(before) {
  const value = structuredClone(state.work);
  value.can_write = role === "organization_admin" && !sourceUnavailable;
  value.assigned = person(value.assigned?.id);
  if (sourceUnavailable)
    return {
      ...value,
      state: "unavailable",
      binding: null,
      history: [],
      next_before_version: null,
    };
  const history = value.history.filter(
    (entry) => !before || entry.version < Number(before),
  );
  return {
    ...value,
    history: history.slice(0, 1),
    next_before_version: history.length > 1 ? history[0].version : null,
  };
}
try {
  reset(domain);
  await wait(async () => (await fetch(base)).ok, "Next did not start");
  let debugPort;
  await wait(async () => {
    debugPort = (
      await readFile(join(profile, "DevToolsActivePort"), "utf8")
    ).split("\n")[0];
    return !!debugPort;
  }, "Chrome did not start");
  const target = await fetch(
    `http://127.0.0.1:${debugPort}/json/new?about:blank`,
    { method: "PUT" },
  ).then((r) => r.json());
  cdp = new Cdp(target.webSocketDebuggerUrl);
  await cdp.send("Page.enable");
  await cdp.send("Runtime.enable");
  cdp.on("Runtime.exceptionThrown", ({ exceptionDetails }) =>
    errors.push(
      exceptionDetails.exception?.description || exceptionDetails.text,
    ),
  );
  cdp.on("Fetch.requestPaused", async ({ requestId, request }) => {
    try {
      const url = new URL(request.url),
        path = url.pathname,
        body = request.postData ? JSON.parse(request.postData) : null;
      requests.push({
        path: request.url,
        method: request.method,
        domain,
        user,
      });
      let data = {},
        code = 200;
      if (path === "/api/auth/session")
        data = {
          authenticated: true,
          user: {
            id: user,
            name: user,
            email: "fixture@example.invalid",
            locale,
          },
          organization: { id: "org-a", name: "Synthetic workspace" },
          role,
          platform_admin: false,
          onboarding_required: false,
        };
      else if (path === "/api/health")
        data = {
          status: "ok",
          database: "synthetic",
          apertus: { configured: false },
          firecrawl: { configured: false },
        };
      else if (path === "/api/assistant/context")
        data = { context: { entity: null }, persona: { quip_allowed: false } };
      else if (path === "/api/jobs") data = [];
      else if (path.startsWith("/api/monitoring-centre/business")) {
        if (denied) {
          code = 404;
          data = { code: "business_item_not_found" };
        } else if (path.endsWith("/members"))
          data = {
            items: [
              { id: "owner", name: "Owner" },
              { id: "peer", name: "Peer" },
            ],
            next_cursor: null,
          };
        else if (path.endsWith("/work")) {
          if (request.method === "POST") {
            writes.push({ domain, body, user });
            if (conflict) {
              code = 409;
              data = { code: "business_item_changed" };
            } else {
              assert.equal(role, "organization_admin");
              assert.equal(body.expected_version, state.work.version);
              assert.deepEqual(body.expected_binding, state.work.binding);
              assert.ok(!sourceUnavailable);
              state.work.version++;
              state.detail.version = state.work.version;
              state.work.assigned = person(body.assigned_user_id);
              if (body.decision) {
                state.work.decision = body.decision;
                state.work.needs_review = false;
                state.detail.decision = body.decision;
                state.detail.needs_review = false;
                state.detail.review_state = "reviewed";
                state.detail.reviewed_sequence =
                  state.detail.sequence || state.detail.material_sequence;
              }
              state.work.history.unshift({
                id: `event-${state.work.version}`,
                version: state.work.version,
                state: "available",
                binding: structuredClone(state.work.binding),
                older_evidence: false,
                actor: person(user),
                assigned: person(body.assigned_user_id),
                comment: body.comment,
                decision: body.decision,
                created_at: "2026-09-14T12:00:00Z",
              });
              data = workPage();
            }
          } else {
            data = workPage(url.searchParams.get("before_version"));
            if (delayed) {
              held = { requestId, data };
              return;
            }
          }
        } else data = {};
      } else if (path.startsWith(`/api/${routes[domain]}`)) {
        if (denied) {
          code = 404;
          data = { code: "business_monitor_not_found" };
        } else if (path.endsWith("/capabilities"))
          data = {
            drafts_available: true,
            public_source_available: true,
            lookback_days: 90,
            cycle_hours: 6,
          };
        else if (path.endsWith("/source-status"))
          data = {
            state: "permission_required",
            traversal: null,
            source: null,
          };
        else if (path.endsWith(`/monitors/${state.monitor.id}`))
          data = state.monitor;
        else if (path.endsWith("/monitors"))
          data = { items: [state.monitor], next_cursor: null };
        else if (path.endsWith("/revisions"))
          data = {
            items: [
              { revision: 1, configuration: state.monitor.configuration },
            ],
            next_cursor: null,
          };
        else if (path.endsWith(`/${state.detail.id}`)) data = state.detail;
        else if (
          ["/dossiers", "/candidates", "/items"].some((end) =>
            path.endsWith(end),
          )
        ) {
          const assignment = url.searchParams.get("assignment");
          const visible =
            !assignment ||
            (assignment === "mine"
              ? state.work.assigned?.id === user
              : !state.work.assigned);
          data = {
            ...state.page,
            items: visible
              ? state.page.items.map((item) => ({ ...item, ...state.detail }))
              : [],
          };
        } else
          data = {
            items: [],
            next_cursor: null,
            health: "waiting",
            coverage_verified: false,
          };
      }
      await response(requestId, data, code);
    } catch (error) {
      errors.push(String(error));
      await response(requestId, { code: "fixture_failure" }, 500);
    }
  });
  await cdp.send("Fetch.enable", {
    patterns: [{ urlPattern: "*/api/*", requestStage: "Request" }],
  });
  await cdp.send("Network.setCookie", {
    name: "helvetic_lens_csrf",
    value: "synthetic",
    url: base,
  });
  for (const kind of visual ? ["tenders"] : Object.keys(routes))
    for (const language of visual ? ["en-CH"] : Object.keys(businessItemCopy))
      for (const width of [390, 1440]) {
        reset(kind);
        locale = language;
        const c = businessItemCopy[locale];
        await cdp.send("Emulation.setDeviceMetricsOverride", {
          width,
          height: 1000,
          deviceScaleFactor: 1,
          mobile: width === 390,
        });
        await navigate();
        await open();
        await check(`${kind}-${language}-${width}-empty`);
        await value("[data-business-item-assignee]", "peer");
        await value(
          "[data-business-item-comment]",
          "Check evidence <script>window.commentInjected=true</script>",
          "textarea",
        );
        const count = writes.length;
        await button(c.save);
        await wait(() => writes.length === count + 1, "Note not saved");
        assert.equal(state.work.needs_review, true);
        assert.equal(state.work.decision, null);
        await open();
        await value(
          "[data-business-item-decision]",
          { tenders: "no_bid", ip: "counsel", auctions: "inspect" }[kind],
        );
        await value(
          "[data-business-item-comment]",
          "Decision rationale for this exact evidence",
          "textarea",
        );
        await button(c.decide);
        await wait(() => writes.length === count + 2, "Decision not saved");
        assert.equal(state.work.needs_review, false);
        assert.equal(state.work.history[0].assigned.id, "peer");
        await open();
        await button(c.earlier);
        await wait(
          () =>
            evaluate(
              cdp,
              "document.querySelectorAll('[data-business-work-entry]').length===2",
            ),
          "History pagination missing",
        );
        assert.equal(await evaluate(cdp, "!!window.commentInjected"), false);
        await check(`${kind}-${language}-${width}-decision`);
        if (visual) {
          await evaluate(
            cdp,
            "document.querySelector('[data-business-item-work]').scrollIntoView({block:'start'})",
          );
          await writeFile(
            join(root, `test-results/business-item-work-${width}.png`),
            Buffer.from(
              (await cdp.send("Page.captureScreenshot", { format: "png" }))
                .data,
              "base64",
            ),
          );
        }
      }
  locale = "en-CH";
  for (const kind of visual ? [] : Object.keys(routes)) {
    reset(kind);
    state.monitor.visibility = state.work.visibility = "private";
    const privateStart = requests.length;
    await navigate();
    await open();
    assert.deepEqual(
      await evaluate(
        cdp,
        "[...document.querySelector('[data-business-item-assignee]').options].map(o=>o.value)",
      ),
      ["", "owner"],
    );
    assert.equal(
      requests
        .slice(privateStart)
        .filter((r) => new URL(r.path).pathname.endsWith("/members")).length,
      0,
    );
    await check(`${kind}-private-creator`);
    reset(kind);
    state.work.history = [
      {
        id: "old",
        version: 1,
        state: "available",
        binding: state.work.binding,
        older_evidence: true,
        actor: person("owner"),
        assigned: person("owner"),
        comment: "Older evidence reasoning",
        decision: "monitor",
        created_at: "2026-09-12T12:00:00Z",
      },
      { id: "withheld", version: 0, state: "unavailable" },
    ];
    role = "viewer";
    user = "viewer";
    const start = requests.length;
    await navigate();
    await open();
    assert.equal(
      await evaluate(
        cdp,
        "!!document.querySelector('[data-business-item-comment]')",
      ),
      false,
    );
    assert.equal(
      requests
        .slice(start)
        .filter((r) => new URL(r.path).pathname.endsWith("/members")).length,
      0,
    );
    await button(businessItemCopy[locale].earlier);
    await check(`${kind}-viewer-history`);
    user = "peer";
    role = "organization_admin";
    await navigate();
    await open();
    conflict = true;
    await value(
      "[data-business-item-comment]",
      "stale colleague note",
      "textarea",
    );
    await button(businessItemCopy[locale].save);
    await wait(
      () =>
        evaluate(
          cdp,
          "!document.querySelector('[data-business-item-comment]')",
        ),
      "Failed input retained",
    );
    conflict = false;
    await navigate();
    await open();
    await check(`${kind}-conflict-reload`);
    sourceUnavailable = true;
    await navigate();
    await open();
    assert.equal(
      await evaluate(
        cdp,
        "!!document.querySelector('[data-business-item-comment]')",
      ),
      false,
    );
    await check(`${kind}-source-unavailable`);
    reset(kind);
    await navigate(false);
    const position = requests.length;
    await value("[data-business-assignment-filter]", "mine");
    await wait(
      () =>
        requests
          .slice(position)
          .some((r) => r.path.includes("assignment=mine")),
      "Assignment filter did not query native list",
    );
    await navigate();
    delayed = true;
    await click("[data-business-item-work] summary");
    await wait(() => !!held, "Missing delayed work read");
    await evaluate(cdp, "window.dispatchEvent(new Event('pagehide'))");
    delayed = false;
    await response(held.requestId, held.data);
    held = null;
    await sleep(250);
    assert.equal(
      await evaluate(
        cdp,
        "!!document.querySelector('[data-business-item-comment]')",
      ),
      false,
    );
    reset(kind);
    await navigate();
    await open();
    denied = true;
    await button(businessItemCopy[locale].reload);
    await wait(
      () =>
        evaluate(
          cdp,
          "!document.querySelector('[data-business-item-comment]')&&!!document.querySelector('[data-business-item-work] [role=alert]')",
        ),
      "Withdrawn scope kept work content",
    );
    await check(`${kind}-access-withdrawn`);
  }
  assert.deepEqual(errors, []);
  audit.finish(visual ? 4 : 75);
  await writeFile(
    join(
      root,
      visual
        ? "test-results/business-item-visual-requests.json"
        : "test-results/business-item-work-requests.json",
    ),
    JSON.stringify({ writes, requests }, null, 2),
  );
  console.log(
    visual
      ? "Tender item-work desktop/mobile screenshots saved; four accessibility checkpoints passed."
      : "Three native item panels: assignment, comment-only, combined decision, five locales/two widths, viewer, history, conflict, source/access withdrawal, filters and pagehide verified.",
  );
} finally {
  cdp?.close();
  browser.kill();
  server.kill();
  await sleep(250);
  await rm(profile, {
    recursive: true,
    force: true,
    maxRetries: 8,
    retryDelay: 250,
  }).catch(() => {});
}
